const sharp = require('sharp');
const path = require('path');

async function optimizeImages(inputDir, outputDir) {
  const images = require('glob').sync('**/*.{jpg,jpeg,png,svg}', inputDir);

  for (const imagePath of images) {
    const inputPath = path.join(inputDir, imagePath);
    const outputPath = path.join(outputDir, imagePath);

    await sharp(inputPath)
      .resize(1200, 630, { fit: 'inside' }) // Responsive size
      .webp({ quality: 80 }) // Modern format
      .toFile(outputPath.replace(/\.(jpg|jpeg|png)$/, '.webp'));

    console.log(`Optimized: ${imagePath} → ${path.basename(outputPath)}`);
  }
}

